import{_ as o,o as n,c as s,ae as r}from"./chunks/framework.EHGTsUvI.js";const p="/assets/transformer-1.D6tbLUBh.png",a="/assets/transformer-2.Bkebo6XY.png",i="/assets/transformer-3.Cl88OX_U.png",g="/assets/transformer-4.Bkan_U0N.png",l="/assets/transformer-5.ZDOPBjZb.png",d="/assets/transformer-10.D4lqse5O.png",c="/assets/transformer-6.CIa4Me5Y.png",m="/assets/transformer-7.DaJj2Pej.png",u="/assets/transformer-8.CNsAcZ4A.png",k="/assets/transformer-9.BvlkzcK8.png",h="/assets/transformer-11.UY9LxBYY.png",b="/assets/transformer-12.Djb7YZHS.png",f="/assets/transformer-13.BsW4TMPW.png",q="/assets/transformer-14.gaPUEJt0.png",_="/assets/transformer-15.BurZml5J.png",E="/assets/transformer-16.iTX3gtbg.png",v="/assets/transformer-17.DqDUFW5D.png",A="/assets/transformer-18.XUOg7cng.png",y="/assets/transformer-19.CNNHF5w0.png",I="/assets/transformer-20.CGOMSj45.png",x="/assets/transformer-21.C-2I2BPn.png",S="/assets/transformer-22.D83WWZeg.png",F="/assets/transformer-23.BxYU1nCY.png",W="/assets/transformer-24.S5u5Ms-k.png",e="/assets/transformer-25._H0HYDlT.png",T="/assets/transformer-27.MKidcHVh.png",N="/assets/transformer-26.BY68mZWD.png",w=JSON.parse('{"title":"Transformer底层逻辑：从token到生成","description":"","frontmatter":{},"headers":[],"relativePath":"AI/transformer.md","filePath":"AI/transformer.md"}'),B={name:"AI/transformer.md"};function O(P,t,$,C,V,D){return n(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="transformer底层逻辑-从token到生成" tabindex="-1">Transformer底层逻辑：从token到生成 <a class="header-anchor" href="#transformer底层逻辑-从token到生成" aria-label="Permalink to &quot;Transformer底层逻辑：从token到生成&quot;">​</a></h1><p>内容参考自<a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">The Illustrated Transformer</a>，非常棒的文章。</p><p>再加上一些深入的补充以及一些理解</p><h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>我们从一个非常简单又常用的情景开始：翻译。输入一个句子，经过model处理，输出它的法语翻译</p><p><img src="'+p+'" alt="image.png"></p><p>Transformer 模型在其中做了什么事呢？这里以 Encoder-Decoder 架构（如原始翻译场景）为例，就能发现它是由两大主要部分组成：<strong>Encoders</strong> 和 <strong>Decoders</strong></p><p><img src="'+a+'" alt="image.png"></p><p><strong>Encoders</strong>是由一组encoder组成(堆叠层数 N 是超参数，原始论文为 N=6，现代模型一般为 12、24、32 层不等)。<strong>Decoders</strong>则是由一组decoder组成</p><p><img src="'+i+'" alt="image.png"></p><p>每个encoder在<strong>结构</strong>上都是一摸一样的。注意，仅仅在<strong>结构</strong>上一样，在<strong>权重</strong>上是不一样的(关于权重，这个后面会讲到)。每个encoder由两部分组成: S<strong>elf-Attention</strong>和<strong>Feed Forward Neural Network</strong></p><p><img src="'+g+'" alt="image.png"></p><p>输入进入encoder层后，首先会流入self-attention层。该层帮助encoder在encode特定单词时关注输入句子中的其他单词。我们将在本文后面更详细地探讨self-attention机制。</p><p>self-attention层的输出会被喂给FFNN(Feed Forward Neural Network)层。</p><p>decoder层同样也有self-attention和FFNN, 但与encoder不同的是，它多了一层Encoder-Decoder Attention层，也叫Cross-attention层</p><p><img src="'+l+'" alt="image.png"></p><p>以上就是Encoder和Decoder的概述。接下去我们深入到核心部分 <strong>Encoder</strong></p><h1 id="let-us-encoding-embedding" tabindex="-1">Let us <s>encoding</s> embedding <a class="header-anchor" href="#let-us-encoding-embedding" aria-label="Permalink to &quot;Let us ~~encoding~~ embedding&quot;">​</a></h1><p>从概述部分的例子，我们了解到了输入（<em>I am Batman</em>）会先流入encoder层，然后经过一系列处理最终输出(<em>Je suis Batman</em>)。这里就产生了一个疑问：encoder怎么会认识 “I am Batman”这句话？如果我改成 “我是蝙蝠侠” / “Ik ben Batman” / … 等不同的语言，显然同样可以成功。为什么呢？encoder，或者说Transformer怎么能懂这么多国的语言呢 ？</p><p>答案就是：不，它不懂，它只知道数学运算。</p><p>在输入传入encoder之前，会先进行一个很重要的必需的操作：<strong>Embedding</strong></p><p>在 PyTorch 等主流框架中，输入矩阵 X 的 shape 为 $[seq_len, d_{model}]$，即每一行对应一个 token 的 embedding 向量，这样才能直接右乘权重矩阵 W。行向量就是一个 1✖️n 的矩阵，我们描述一个矩阵的形状，通常说这个矩阵是几行几列的，比如3✖️4 就是一个三行四列的矩阵。与Transformer打交道的就是矩阵。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>在研究Transformer的过程中经常可以看到说某个矩阵其维度为：$[batch_size, seq_len, d_{model}]$</p><ul><li><p>$batch_size$: <strong>一次并行处理的样本数量</strong>。比如值为2，就代表同时处理两句话。</p><p>“<em>可能你会有疑问。怎么算两句话，用句号问号等标点符号区分吗？这段话算几句话？</em>” 这算一句话。因为标点符号只是软约束，是概率模式，而不是硬约束。默认情况下，模型不会把它“结构化地”识别成两句话，只会当成一个连续 token 序列处理。</p><p>要想显式地把句子分成多句话，可以采用分隔符 <strong>[SEP]</strong>, 比如: &quot;AI is helpful.[SEP] I love AI&quot;， 此时$batch_size$=2。</p><p>还有一种方法是完全拆开: batch = [&quot;AI is helpful&quot;, &quot;I love AI&quot;] 这样两句话完全独立，不共享attention</p></li><li><p>$seq_len$ : 每个序列的<strong>token 数</strong>（有多少行）</p></li><li><p>$d_{model}$: 每个 token 的<strong>向量维度</strong>，也叫隐藏状态维度(有多少列)</p></li></ul></div><p>这里展示了一个1✖️4和一个3✖️4的矩阵，下标代表该参数所在的行列数</p><p><img src="'+d+'" alt="image.png"></p><p>这里我们传给encoder的是一句话”I am Batman”，这句话是怎么被embedding成矩阵的呢？矩阵中的数字又是什么呢？</p><p>在Embedding之前，还需要一个操作，叫做<strong>Tokenization。</strong> 顾名思义，就是把prompt(也就是输入的句子)分成一个个单词。</p><p><img src="'+c+'" alt="image.png"></p><p>这里”I am Batman”被分成了三个单词，尽管经过tokenizer,句子已经成为一个个单词了，但它们还是人类的单词，transformer只与矩阵打交道。那么接下来就要把一个个单词转化为向量，再把这些向量组合起来，矩阵就出现了。想象有一张很大的vocabulary表，并给每个单词约定了一个id，类似于：</p><p><img src="'+m+'" alt="image.png"></p><blockquote><p>此处仅为示意，实际模型词表大小因设计而异</p></blockquote><p>每一个单词几乎都有了对应的ID。为什么说几乎呢，因为有些单词是不同的时态表示或者结尾带了 <strong>‘s,</strong> 更何况人们隔三差五就会创造出一个新词，所以显然不会也不能把所有的单词都录入进这张vocabulary表中，但是在tokenization的时候可以把这种”特殊单词“拆分，找到它们各自的id，再组合起来。比如”I am Batman’s enemy”, 其中”Batman’s” 就会被分成”Batman” 和 “’s”， 然后在表中找到各自映射的id，从而就有了”Batman’s”这类单词的表示。</p><p>也许你已经注意到了，用“单词”这个说法并不准确。实际上，它们被称作“token”，token可以是英语单词，也可以是”##le”，甚至可以是“🍎”。 这很好地与tokenization联系了起来。也可以联想到AI公司提供LLM的api都明确标注了价格，比如$4/million token</p><p>在完成 tokenization 之后，每个 token 会被映射为一个离散的 token id，这个id不携带意义，没有大小关系，没有语义，只是一个索引。接下来进入到embedding。</p><p>Transformer 并不会直接对离散 id 进行计算，而是通过一个 embedding layer，将 token id 映射为一个连续向量。即embedding 层仅根据 token id 从已训练好的 embedding 矩阵中查找对应向量，即又是一个查表的操作。在推理阶段，参数保持冻结，不参与损失计算或梯度更新。在训练阶段则是<strong>可训练参数</strong>，会通过反向传播被更新。</p><p><img src="'+u+'" alt="image.png"></p><p>一个token对应一个向量，多个token就组成了一个矩阵。这个表是怎么来的呢？我们前面描述的 Embedding阶段的查表操作是在Inference(推理)阶段才会这么做，这么做的前提是Training / Pre-training / Fine-tuning（训练）阶段训练好了这张表。训练阶段做了什么呢？</p><p>在训练阶段，embedding 矩阵作为 Transformer 模型的可训练参数之一，通过反向传播和梯度下降最小化语言建模损失，即优化损失函数；训练完成后，该矩阵参数被冻结，在推理阶段仅用于根据 token id 查询对应的向量表示。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>最开始的，未被训练的embedding矩阵是通过随机初始化得到的，<strong>不包含任何语义信息</strong>，只是满足数值稳定性的随机值。来自于均匀分布，正态分布等。</p></div><p>然而组成句子的 token 集合可能完全相同，但不同的顺序会导致语义发生变化，比如[&quot;dog&quot;, &quot;bites&quot;, &quot;man&quot;] 和 [&quot;man&quot;, &quot;bites&quot;, &quot;dog&quot;]会产生完全相同的attention分布。在 Transformer 中，encoder层中的 self-attention 的计算本身对输入顺序是置换不敏感的，如果仅使用 token embedding，模型无法区分这类顺序不同但 token 相同的句子。因此，必须在构造 encoder 输入表示时显式引入位置信息。传统做法是使用sin / cos 生成positional embedding， <strong>PE 与 token embedding 维度相同（均为 d_model），对应位置逐元素相加</strong>，从而使后续的 attention 计算能够同时利用语义信息和位置信息。现代模型已经改用旋转位置编码(RoPE)。</p><p><img src="'+k+'" alt="image.png"></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><p>你可能会有疑问：E与PE相加后，会不会出现等于另一个E / E+PE 这种情况？</p><p>不会。高维空间中向量的数量远大于词汇表的大小，embedding 向量之间的距离分布集中在一个较大的均值附近，因此两个不同 token 的 embedding 向量相加后的结果几乎不会与第三个 token 的 embedding 重合</p></div><h1 id="let-us-encoding" tabindex="-1">Let us encoding <a class="header-anchor" href="#let-us-encoding" aria-label="Permalink to &quot;Let us encoding&quot;">​</a></h1><p>这是一张encoder层的概览。在完成之前的步骤后，一组向量（即一个矩阵）作为输入传入<strong>self-attention</strong>层，接着流入feed-forwar neural network层，然后作为该层encoder的输出流入下一层encoder</p><p><img src="'+h+'" alt="image.png"></p><p>好，现在我们知道了“一个矩阵作为输入流入了第一层encoder，然后做了一些计算，输出的计算结果又作为第二层encoder的输入再进行一些计算” 。那么里面到底做了什么计算呢？在深入了解核心的<strong>self-attention</strong>层做了什么之前，我们先来看这么一句话：</p><h5 id="the-animal-didn-t-cross-the-street-because-it-was-too-tired" tabindex="-1">”<code>The animal didn&#39;t cross the street because it was too tired</code>” <a class="header-anchor" href="#the-animal-didn-t-cross-the-street-because-it-was-too-tired" aria-label="Permalink to &quot;”`The animal didn&#39;t cross the street because it was too tired`”&quot;">​</a></h5><p>这句话里的 &quot;it&quot; 指的是什么？The animal 还是 the street ？对人类来说这个问题很简单，但模型是怎么知道的呢。</p><p>当模型处理每个单词（输入序列中的每个位置）时，自注意力机制使其能够查看输入序列中的其他位置，查找每个词和其他词之间的联系，寻找有助于更好地编码该单词的线索。</p><p><img src="'+b+'" alt="image.png"></p><p>你可以通过在 <a href="https://colab.research.google.com/github/tensorflow/tensor2tensor/blob/master/tensor2tensor/notebooks/hello_t2t.ipynb" target="_blank" rel="noreferrer">Tensor2Tensor notebook</a> 中试验来查看每个词与其他词之间的关联程度</p><p>接下来我们来详细了解如何用向量进行self-attention的计算</p><h3 id="self-attention" tabindex="-1">Self-Attention <a class="header-anchor" href="#self-attention" aria-label="Permalink to &quot;Self-Attention&quot;">​</a></h3><p>计算self-attention的<strong>第一步</strong>是将每个输入的向量与：Query矩阵，Key矩阵，Value矩阵 这三个权重矩阵分别相乘得到query向量，key向量和value向量。因此，如果输入有3个token（图中所示），那么就会有3组query,key,value向量</p><p><img src="'+f+`" alt="image.png"></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>你可能会疑问Query矩阵，Key矩阵，Value矩阵这三个权重矩阵是什么，它们是怎么来的？</p><p>在训练阶段之前，它们就是由深度学习框架（如Tensorflow, pyTorch）随机生成的复合特定分布（如正态分布）的参数矩阵。真正赋予它们“灵魂”是在训练过程中。</p><p><u>训练是在已知<strong>标签（Label）的前提下，通过梯度下降算法更新模型参数（Weights）</strong>，从而<strong>最小化</strong>损失函数，使模型的输出分布不断接近真实数据的分布的过程。</u> 其中包括前向传播，计算损失，反向传播，参数更新这几个过程，其中参数更新就是根据梯度更新矩阵中的数值。在经过百万次的迭代之后，这三个矩阵逐渐学到了如何提取有意义的特征。</p><p>例如：W_Q 可能会学到在处理动词时，去寻找句子中的主语特征; W_K可能会学到在处理名词时，将其标记为潜在的主语或宾语特征，以便回应W_Q 的寻找;W_V可能会学到在识别到核心实体时，提取其具体的语义信息（如词义、词性或时态），作为最终输出的实质内容。这只是拟人化的解释，实际这三个矩阵的 512 或 1024 个维度往往是<strong>高度抽象且交织</strong>的</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li><strong>Q (Query)</strong>：当前 Token 正在“寻找”什么。</li><li><strong>K (Key)</strong>：当前 Token 能向其他 Token “提供”什么。</li><li><strong>V (Value)</strong>：当前 Token 携带的“具体信息”。</li></ul></div><p>query,key,value向量又代表什么呢？可以用一个python字典来类比：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;color&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;blue&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;age&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;type&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pickup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> d[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;color&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>当你在普通字典中查找<code>query</code>时，字典会找到匹配的<code>key</code>，并返回其对应的<code>value</code>。<code>query</code>要么有匹配的<code>key</code>，要么没有。你可以想象一个模糊字典，其中键不必完全匹配。如果你在上面的字典中查找 <code>d[&quot;species&quot;]</code>，你可能希望它返回 <code>pickup</code>，因为这是与查询最匹配的结果。Attention层执行类似这样的模糊查找，但它并非仅仅寻找最佳<code>key</code>。它会根据<code>query</code>与每个<code>key</code>的匹配程度来组合<code>values</code>。</p><p>它是如何工作的呢？在attention层中，<code>query</code>、<code>key</code>和<code>value</code>都是向量。attention层并不执行哈希查找，而是将<code>query</code>向量和<code>key</code>向量组合起来，以确定它们的匹配程度，即“attention score”。该层返回values的平均值，并根据“attention score”进行加权。</p><p>查询序列中的每个位置都提供一个查询向量。上下文序列充当字典。上下文序列中的每个位置都提供一个键向量和一个值向量。输入向量不会被直接使用。</p><p>这也就是计算self-attention的<strong>第二步</strong>：计算attention score。该分数决定了在对特定位置的单词进行encode时，应该给予输入句子的其他部分多少关注。因此我们需要根据这个词对输入句子中的每个词进行评分。</p><p><img src="`+q+'" alt="image.png"></p><p>如图所示，attention score的计算方式是将<code>query</code>向量与待评分词的<code>key</code>向量进行点积运算。比如，要计算第一个单词的self-attention,第一个分数就是q1与k1的点积，代表词&quot;I&quot;对其自身的attention score，目的是确定在理解“I”这个词时，它本身的特征有多重要。第二个分数就是q1与k2的点积，代表词“I”对第二个词“am”的attention score，目的是确定在理解“I”这个词时，第二个词“am”提供了多少上下文信息。同理，第三个分数就是q1与k3的的点积，代表词“I”对第三个词“Batman”的attention score，目的是确定在理解“I”这个词时，第三个词“Batman”提供了多少上下文信息。</p><p><strong>第三步</strong>, 由于随机初始化的向量做点积后，其方差约为 $d_k$，因此点积的量级随 $d_k$ 线性增大, 因此将得到的score<strong>除以 $√d_k$（此处 $d_k$=64，故为8），目的是控制点积的方差量级，防止 Softmax 进入饱和区间, 导致梯度消失</strong></p><p><strong>第四步</strong>是将第三步得到的值转为概率分布，实现加权关注，即：Softmax。Softmax 会对分数进行归一化处理，使它们全部为正数且总和为 1。</p><p><img src="'+_+'" alt="image.png"></p><p><strong>第五步</strong>是将每个value向量乘以softmax score。这一步完成了信息的加权聚合。如果说之前<strong>q</strong>,<strong>k</strong>是在寻找关联，那么这一步就是在提取并融合信息。Softmax算出的概率本质上是<strong>权重</strong>。将权重乘以Value向量，意味着：</p><ul><li><p>高权重(0.65, 0.30)：保留改词的大部分特征信息(value)</p></li><li><p>低权重(0.05)：过滤掉该词大部分无关的信息</p></li></ul><p>也就是说，<strong>q</strong>与<strong>k</strong>的点积只负责算出一个比例：”我该看谁？看多少？“ ， 但并不包含这个词真正的表达内容，只有乘以 v ，模型才能把“注意力比例”转化为“具体的语义表示”。如果没有这一步，模型只知道谁重要，但拿不到重要的数据。</p><p>所以softmax乘以value向量，再将结果相加的意义就是：<strong>利用计算出的注意力分布，动态地从所有输入词中提取相关特征，并将它们聚合成一个包含上下文信息的全新向量</strong>。</p><p><img src="'+E+'" alt="image.png"></p><p>上述步骤的计算结果就会继续流入feed-forward neural network层。在实际实现中，为了加快处理速度，该计算以矩阵形式进行（将同维度的向量组合起来其实就是矩阵，所以在理解上并没有什么不同）</p><p><strong>首先</strong>将由一个个token经过embedding+positional-embedding组成的<strong>输入矩阵X</strong>去乘以<strong>Query, Key, Value 三个权重矩阵</strong>得到<strong>Query, Key, Value矩阵</strong></p><p><img src="'+v+'" alt="image.png"></p><p><strong>最后</strong>，由公式输出 Z</p><p><img src="'+A+'" alt="image.png"></p><p>想象你想自制一杯咖啡，Softmax 告诉你是“65% 的浓缩咖啡”加“30% 的牛奶”加“5%的厚奶泡”。乘以 <strong>v</strong> 的过程就是根据这个配方，真正把咖啡液和牛奶倒进杯子里混合。最后得到的 <strong>z</strong> 就是那杯调好的<strong>卡布奇诺</strong>。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Z的行数严格等于输入序列的长度</strong>。</p><p>从向量的视角看的话，第一个token生成的z1在Z的第一行，第二个token生成的z2在Z的第二行 ....</p></div><h3 id="multi-head-attention" tabindex="-1">Multi-Head Attention <a class="header-anchor" href="#multi-head-attention" aria-label="Permalink to &quot;Multi-Head Attention&quot;">​</a></h3><p>到这里，你应该对single-head attention有了一定的认知。然而如果只有single-head，所有的语义关系都只能在同一个投影子空间里表达，不同类型的关系（语法依赖、指代关系、位置关系、语义相似）会互相干扰。而multi-head attention则允许模型运行8个（或更多）独立的计算过程，比如</p><ul><li><strong>头 1</strong> 专注于代词指代（“I” 指向谁？）。</li><li><strong>头 2</strong> 专注于时态（“am” 代表现在时）。</li><li><strong>头 3</strong> 专注于情感或特定专有名词（“Batman” 的特殊含义）</li><li>....</li></ul><blockquote><p>这只是直觉上的拟人化描述，实际上每个头学到的模式是通过训练涌现的，并不可预先指定</p></blockquote><p><strong>Multi-head 是怎么实现的？</strong></p><p>在实际实现中，通常依然先用输入矩阵X乘以W<sup>Q</sup>,W<sup>K</sup>,W<sup>V</sup>这三个权重矩阵，然后将每个高维矩阵切分成h个局部低维矩阵。例如，总维度 512 被切成 8 个 64 维的向量(维度就是矩阵拥有的列数)。也就是<strong>先乘，再分维度</strong>。</p><p>从数学上看，它做的是：</p><p><img src="'+y+'" alt="image.png"></p><p>每个 head 有自己独立的$W_Q$<sup>i</sup>， $W_K$<sup>i</sup>， $W_V $<sup>i</sup>，然后分别乘以输入，也就是<strong>先分维，再乘</strong>。</p><p>可以发现，在数学表达能力上两者等价，实际实现中通常采用前者以利用 GPU 的大矩阵运算效率。</p><p><strong>切分</strong>完成后，将这三对各8组矩阵分别独立进行刚才的<code>Score -&gt; Softmax -&gt; Weighting</code> 过程,也就是8个单头计算，每个头计算结束都会输出一个<strong>该头的Z</strong>，总共输出8个相同形状的Z矩阵(n行64列，n取决于输入序列，还记得吧)。</p><p>接着把8个头的输出<em>Z1,Z2 ... Z8</em>横向拼接在一起, 最后再乘一个权重矩阵 W<sup>O</sup>。最终得到一个流向FFNN的矩阵 --- 大写的Z矩阵</p><p><img src="'+I+'" alt="image.png"></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><p>矩阵的横向拼接是指增加列数，如每个单头输出的 <strong>Z</strong> 的拼接</p><p>矩阵的纵向拼接是指增加行数，如每个单头中每个token对应的输出 <strong>z</strong> 的拼接</p></div><p>下面是整个流程的示意图：</p><p><img src="'+x+'" alt="image.png"></p><p>整个过程就相当于：把一个高维空间拆成多个“语义子空间”，分别建模不同关系。</p><p>想象你在评估一个<strong>球员（输入 X）</strong>：</p><ul><li><strong>头 1（球探视角）</strong>：关注他的体能、速度、爆发力。</li><li><strong>头 2（战术分析视角）</strong>：关注他的跑位、团队配合、防守意识。</li><li>......</li><li><strong>头 8（商业视角）</strong>：关注他的商业价值、粉丝影响力。</li></ul><p>最后，你把这些视角的结论汇总，就得到了对这个球员<strong>最全面、立体</strong>的评价</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>你可能会同我一样，产生以下几个疑问：</p><p>问：为什么要乘以一个权重矩阵 W<sup>O</sup>？</p><p>答：W<sup>O</sup> 承担了**“融合”<strong>与</strong>“统一”<strong>的任务，最终与W<sup>O</sup> 相乘的那个矩阵的每一个维度都融合了来自不同“头”的特征信息，W<sup>O</sup>让来自不同头的信息进行单向的</strong>跨头交换**, 决定“如何整合所有视角的发现”（产生最终表示）。</p><p>问：切开再拼凑的意义是什么？</p><p>答：如果不平均切开，再拼凑，而是直接将输入X与权重矩阵相乘后再直接与W<sup>O</sup>相乘，这就相当于一个single-head与W<sup>O</sup>相乘，那么single-head与multi-head的区别就是是否有W<sup>O</sup>矩阵，显然这是荒谬的。 因为切--&gt;拼的过程中发生的不单是这个看似多余的操作，实则通过“切分”，我们强制模型在 h 个<strong>独立的低维子空间</strong>内都进行 Softmax 归一化。每个头产生的注意力分布（那些0.65，0.05，0.30）是完全不同的，因为<strong>Softmax 是非线性的</strong>。每个头都在自己的空间里做“信息竞争”。比如头 1 在关注“主谓关系”，头 2 在关注“代词指代”。如果不切，所有的特征（语法、语义、时态）被迫在同一个 Softmax 里竞争。由于 Softmax 的特性，它倾向于让“最强”的那个特征统治全局，从而<strong>抹杀了其他弱势但重要的特征</strong>，就失去了多头注意力的多维度观察能力</p></div><h3 id="the-residuals" tabindex="-1">The Residuals <a class="header-anchor" href="#the-residuals" aria-label="Permalink to &quot;The Residuals&quot;">​</a></h3><p>在每个encoder中的每个子层（self-attention、ffnn）周围都有一个残差连接: Resudual Connection (Add&amp;norm中的Add).</p><p>Add做的事其数学表达式极为简洁：<strong>Output = x + Sublayer(x)</strong>。</p><p>Layer norm的任务是将神经元的输出分布重新调整为均值为 0、方差为 1 的标准分布。简单来说，就是将标准化后的向量进行一次线性变换：乘以一个训练出来的系数，再加上一个训练出来的常数。保证了无论输入数据的量级如何波动，传递到下一层的数值始终处于一个“可控”的范围内，从而极大增强了训练的稳定性。</p><p>因此残差层的存在解决深层网络在训练过程中面临的**梯度消失（Gradient Vanishing）<strong>和</strong>模型退化（Degradation）**问题，以及控制每层输出的数值分布，加速训练收敛</p><p><img src="'+S+'" alt="image.png"></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><p>由于残差连接引入了 <strong>x+f(x)</strong> 结构，所以当对这个函数求x的偏导时就会得到 <strong>1+f&#39;(x)</strong> 。这样，即使在反向传播的过程中，f&#39;(x)连续多层都非常小（例如接近于0），有了**“1”**的存在，梯度也不会在传播过程中消失，梯度依然能通过那个 <strong>“1”</strong> 顺畅地流回底层。</p><p>另外，Self-Attention 是一个极具“侵略性”的操作，它会根据上下文大幅度改写词向量的数值，不加残差连接时，原始 token 的局部特征可能被全局聚合结果所覆盖，导致模型难以利用词本身的静态语义。通过 <strong>x + Attention(x)</strong>，模型在获取上下文信息的同时，强制保留了原始输入的特征。这对于保持语义的一致性至关重要。</p></div><p>如果把add和norm操作具像化表示，看起来就是这样子： <img src="'+F+'" alt="image.png"></p><p>一样的模式同样适用于decoder的子层：</p><p><img src="'+W+'" alt="image.png"></p><h3 id="feed-forward-neural-network" tabindex="-1">Feed forward neural network <a class="header-anchor" href="#feed-forward-neural-network" aria-label="Permalink to &quot;Feed forward neural network&quot;">​</a></h3><p>Attention层是负责处理 token 之间的水平交互，那么 FFNN 层就是负责对每个 token 进行 token 内部的特征转换。FFNN的全称叫 <strong>Position-wise</strong> FFNN，意味着它对序列中的每一个位置 x 独立地应用相同的线性变换。其标准结构包含 <u>两个线性层</u> 和一个<em>非线性激活函数:</em></p><p><img src="'+e+'" alt="image.png"></p><p>我们可以从FFNN具体做了什么的过程中理解这个函数：</p><ol><li><p><strong>升维</strong>：将输入维度 d<sub>model</sub>（如 512）投影到一个更高的维度 d<sub>ff</sub>（通常是 4 x d<sub>model</sub>，如 2048)。这个过程并不是简单地填补随机数， 而是模型内部有个学习好的权重矩阵 <strong>W<sub>1</sub></strong>，其形状为(512, 2048)。然后通过计算 **x · W<sub>1 </sub>**就得到了升维后的矩阵</p></li><li><p><strong>激活函数</strong>：一个非线性函数，我们熟知的 x<sup>2</sup>，x<sup>3</sup> 都是非线形函数，但由于计算效率和梯度稳定性的考量，</p></li></ol><p>​ 我们通常使用 <strong>ReLU ( f(x) = max(0, x) ）</strong> 或 GELU。这一步至关重要，它引入了非线性，使模型能够学习复杂的模式。</p><ol start="3"><li><strong>降维</strong>：将维度从 2048 压缩回 512，以便与残差连接（Residual Connection）匹配，只保留对当前预测最有用的信息，剔除噪声。同 样是通过矩阵乘法（乘以一个 (2048, 512) 的矩阵 <strong>W~2~</strong>）实现的。</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>为什么需要引入一个非线形函数？</strong></p><p>我们可以反过来理解，如果过程中没有激活函数，只有线形变换(矩阵乘法)会怎么样？</p><ol><li>假设升维是 h = x · W~1~</li><li>假设降维是 y = h · W~2~</li><li>带入后可得 y = ( x · W~1~) · W~2~ = x · (W~1~ · W~2~)</li><li>W~1~ · W~2~ 只是另一个矩阵 W~new~ , 所以 <strong>y = x · W~new~</strong></li></ol><p>由此可见，由于矩阵乘法满足结合律，任意多个线性层的复合仍是线性变换，因此等价于单个线性层。这样的函数就相当于上学时学过的二维坐标轴上的<strong>线性变换</strong>，纯线性变换只能在高维空间中划出超平面，无法拟合非线性的数据分布，因此，只能在多维空间中画平面来切分数据。但真实世界的数据可能是环形或螺旋形的，线性平面永远无法将其正确切分。</p><p>引入<strong>ReLU</strong> 之后，函数变成了 y = max(0, x · W~1~)· W~2~ 就具备了拟合任何复杂曲线和边界的能力。</p></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p><strong>W~1~<strong>和</strong>W~2~<strong>权重矩阵和Attention层中的</strong>W~Q~,W~K~,W~V~</strong> 三个权重矩阵一样，都是通过海量数据的训练得到的。一开始里面的参数都是随机数，经过升维，激活，降维，变成512维输出，并最终输出一个预测值，再与实际值对比，就得出了一个误差值(Loss)。误差的梯度会顺着网络往回流，如果在之前的 2048 维中，<strong>某个维度的激活导致了最终预测的准确（降低了 Loss）</strong>，梯度优化算法就会<strong>增大</strong> **W~1~<strong>和</strong>W~2~<strong>矩阵中连接该维度的权重。如果某个维度纯粹是噪音，增加了误差，优化算法就会把</strong>W~1~<strong>和</strong>W~2~**矩阵中对应的权重压低，甚至逼近于 0。 就这样，经过海量数据的反复洗礼， **W~1~<strong>和</strong>W~2~**矩阵在数学上自然演化成了一个“过滤器”——高权重的通道保留有用特征，低权重的通道屏蔽无用特征</p></div><p>至此为止，encoder部分就结束了，接下来进入decoder。</p><h1 id="decoder" tabindex="-1">Decoder <a class="header-anchor" href="#decoder" aria-label="Permalink to &quot;Decoder&quot;">​</a></h1><p>我们先来看Decoder的整体架构图：</p><p><img src="'+T+'" alt="image.png"></p><p>在 Transformer 的设计中，Encoder 负责将输入序列编码为上下文感知的隐状态表示；Decoder 负责一边观察着 Encoder 提供的上下文（Context），一边根据已经生成的token，推测下一个token。但这件事有一个矛盾：<strong>训练时知道完整答案，推理时不知道</strong>。模型必须在同一套结构下，既能在训练阶段并行处理整个目标序列（否则训练会慢到无法接受），又能在推理阶段严格保证&quot;不能偷看未来&quot;。解决这个问题的方式，就在Decoder的三层结构中。</p><h3 id="self-attention-1" tabindex="-1">Self-Attention <a class="header-anchor" href="#self-attention-1" aria-label="Permalink to &quot;Self-Attention&quot;">​</a></h3><p>所有<strong>生成任务的本质</strong>就是在回答：</p><blockquote><p>给定输入 x，输出 y 的概率是多少？</p></blockquote><p>根据链式法则，P(y|x) 可以分解为各位置条件概率的连乘，这就是自回归生成的数学基础。在Transformer中是这么表示的：</p><p><img src="'+N+`" alt="image.png"></p><p>含义为：生成第t个token，需要依赖----已经生成的<strong>前t-1个token</strong>， 以及源序列的全部信息<strong>x</strong></p><p>也就说，在decoder中，生成第1个token，需要依赖encoders的输出x</p><p>​ 生成第2个token，需要依赖encoders的输出x， 以及第1个token</p><p>​ 生成第3个token，需要依赖encoders的输出x， 以及第1个和第2个token</p><p>​ 生成第4个token，需要依赖encoders的输出x， 以及第1个和第2个和第3个token</p><p>​ ........</p><p>这也就是decoder中的一个核心：<strong>自回归生成(Autoregressive)</strong>。 &quot;自回归&quot;的字面意思是: <strong>用自己过去的输出作为下一步的输入</strong>。但在训练阶段和推理阶段，自回归的输入会有所不同。</p><p>在<strong>推理阶段</strong>，第 $t$ 个词必须依赖第 $t-1$ 个词的结果，这种逻辑依赖在时间轴上是<strong>线性不可并行</strong>的。比如：</p><blockquote><p>已知: &quot;AI is helpful,&quot; → 预测: &quot;I&quot;</p><p>已知: &quot;AI is helpful, I&quot; → 预测: &quot;love&quot;</p><p>已知: &quot;AI is helpful, I love&quot; → 预测: &quot;AI&quot;</p><p>已知: &quot;AI is helpful, I love AI&quot; → 预测: [EOS]</p></blockquote><p>你不知道第1个词是什么，就没法预测第2个词</p><p>在<strong>训练阶段</strong>，是通过 Teacher Forcing 和 Masked self-attention 进行<strong>并行运算</strong>。这是怎么实现的呢？</p><p>假设训练样本还是：</p><blockquote><p>源句：AI is helpful</p><p>目标句：I love AI</p></blockquote><p>模型需要学的是：</p><ul><li>看到 <em>[BOS]</em>, 应该输出&quot;I&quot;</li><li>看到 <em>[BOS] I</em>, 应该输出&quot;love&quot;</li><li>看到 <em>[BOS] I love</em>, 应该输出&quot;AI&quot;</li><li>看到 <em>[BOS] I love AI</em>, 应该输出 [EOS]</li></ul><blockquote><p>【BOS】 就是 Beginning of Sequence 的缩写. [EOF] 是 End of Sequence 的缩写</p></blockquote><p>看起来似乎与推理阶段并无二样，都是根据已有的输入推测出下一个输出。但关键点就在于 <strong>训练时已经知道答案了</strong>。<strong>Teacher forcing</strong>的机制是模型根据源输入 <em>x</em>，推测出第一个输出，但是第二份输入并<strong>不是</strong>由 <strong><em>x</em> + 模型推测出的第一个输出</strong> 组成的(与推理阶段不同)，而是由 <strong><em>x</em> + 答案中对应的第一个词</strong> 组成的。所以在训练阶段，模型推测下一个词永远是基于正确答案的基础上。</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><p>由于推理时，每个位置的输入是<strong>模型自己上一步的输出</strong>，这也意味着一旦某一步出错，错误就会沿着序列传播放大。因为模型训练时的<strong>输入分布</strong>（ground truth token）和推理时的<strong>输入分布</strong>（模型自身预测的 token）之间存在 mismatch，所以输出会一错再错。也就会造成模型<strong>一本正经地胡言乱语</strong>情况的发生，这就是并行训练的代价：**Exposure Bias **(曝光偏移)</p></div><p>那么这是否意味着训练阶段的机制是，已知 <em>x</em> ，得出推测的 <em>y~1~</em>，然后用答案里的 <em>Y~1~</em> 替代 <em>y~1~</em>，接着进行下一步推测呢？ 不是的，因为这样就串行了，训练效率会大打折扣。实际上，思考下训练的目的，<strong>我们不关心模型的预测结果是什么，我们只关心它的损失函数</strong>。而损失函数就是预测值和实际值之间的差别，现在我们已经有了实际值，只需要得到在对应位置的预测值就能计算损失函数。因此整个过程完全可以是并行计算的。</p><p>在当前训练样本中，根据模型需要学的，可以分为4个预测任务：</p><blockquote><p>任务1的输入: [BOS]</p><p>任务2的输入: [BOS] I</p><p>任务3的输入: [BOS] I love</p><p>任务4的输入: [BOS] I love AI</p></blockquote><p>四个任务是并行计算的，每个任务只管根据自己已有的输入推测出输出即可。就能得到一一对应的 预测-实际 对。在实际的实现中，会把这四个任务打包成矩阵: <strong>[[BOS], I, love, AI]</strong> 进行attention计算</p><p>那么问题又来了，整个矩阵一起输入，位置3(&quot;love&quot;)在做attention的时候，会不会偷看到位置4(&quot;AI&quot;)的值呢？ 如果不加任何限制的话，当然会看到。这也就引入了另一个核心的机制: <strong>Masked self-attention</strong>, 这也是并行的关键</p><blockquote><p>Attention Score 矩阵（4×4）：</p><p>​ [BOS] I love AI</p><p>[BOS] [ ✓ ✗ ✗ ✗ ] ← 只能看自己 I [ ✓ ✓ ✗ ✗ ] ← 能看[BOS]和自己 love [ ✓ ✓ ✓ ✗ ] ← 能看前两个和自己 AI [ ✓ ✓ ✓ ✓ ] ← 能看所有</p></blockquote><p>还记得做self-attention时有一个步骤是做 <strong>Softmax</strong> 吗，<strong>将✗位置的 attention score 设为 -∞，使其经过 Softmax 后权重为 0，从而在加权求和 V 时，该位置对当前 token 的输出贡献为零——等效于该位置在计算时不可见。</strong></p><h3 id="cross-attention" tabindex="-1">Cross attention <a class="header-anchor" href="#cross-attention" aria-label="Permalink to &quot;Cross attention&quot;">​</a></h3><p>我们已经了解了decoder的基础层：Masked self-attention。 接下来进入到连接层: Cross attention, 也叫做 <strong>Encoder-Decoder Attention</strong>, 这是decoder最独特的地方。回看decoder整体的架构，可以看到在Encoder-Decoder Attention层，有一个箭头指向它，这个箭头来自Encoder层的输出 <strong>矩阵Z</strong>。为什么Encoder的输出流向Encoder-Decoder Attention呢，为什么不是decoder self-attention？据前文可知，有源输入x，才能推测出第一个词，然后才能推出第二个词吗，现在decoder self-attention什么输入也没有，之前提到的Teacher Forcing + Masked self-attention机制难道没用了吗？</p><p>为了解答这个疑惑，我们同样从训练阶段和推理阶段解析。</p><p>在<strong>推理阶段</strong>，decoder self-attention<strong>并不是没有任何输入</strong>，推理开始时, decoder 有一个<strong>人工给定的起始特殊 token</strong>: [BOS] 。然后推理第一步的完整流程就开始了：</p><p><strong>输入 [BOS]</strong></p><p>----&gt; <strong>Embedding + Positional Embedding</strong></p><p>----&gt; <strong>Masked self-attention</strong></p><p>----&gt; <strong>得到一个隐状态矩阵h</strong></p><p>----&gt; <strong>Q = h * W<sup>Q</sup></strong>（此处 WQ 是 Cross-Attention 层独立的可训练参数，与 Masked Self-Attention 层的 WQ 不共享）</p><p>----&gt; <strong>Cross-attention (与Encoder的K，V结合)</strong></p><p>----&gt; <strong>预测出第一个词</strong></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li><p>和encoder层一样，decoder也有Embedding + Positional Embedding</p></li><li><p>decoder的W<sup>Q</sup>和encoder的W<sup>Q</sup>, W<sup>K</sup>, W<sup>V</sup>一样，一开始也是随机生成的复合特定分布的参数矩阵，而后经过训练的矩阵</p></li><li><p>encoder层的输出是一个矩阵Z，因此这里的与encoder的K，V结合实际说的是decoder 拿到 Z 之后，得到 K 和 V。<strong>Z 在整个解码过程中保持不变，对应的 K 和 V 也只需计算一次，与 Decoder Self-Attention 中随序列增长而扩展的 KV Cache 性质不同</strong></p><p>K = Z * W<sup>K</sup> ← Z 乘以一个可训练的投影矩阵</p><p>V = Z * W<sup>V</sup> ← Z 乘以一个可训练的投影矩阵</p><p>W<sup>K</sup> 和 W<sup>V</sup>是 Cross-Attention 层自己的参数，不是 Encoder 里的。</p><p>因此<strong>K 和 V 不是&quot;保存&quot;在 Encoder 里的，而是每次推理时从 Z 临时投影出来的。</strong></p></li></ul></div><p>在<strong>训练阶段</strong>，decoder self-attention更加不是没有任何输入，相反，训练时，<code>[BOS] I love AI</code> 这个序列是<strong>数据集里直接拿来的</strong>,也就是说self-attention此时拥有完整答案。具体操作是 <strong>Shifted Right</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始目标序列：    I      love    AI    [EOS]</span></span>
<span class="line"><span>Decoder 输入： [BOS]     I     love    AI      ← 整体右移一位</span></span>
<span class="line"><span>Decoder 目标：   I      love    AI    [EOS]    ← 每个位置预测下一个词</span></span></code></pre></div><p>这里预测下一个词就回到了上面所讲的Masked self-attention了。在训练阶段，self-attention需要和cross attention串行结合去推测出下一个词，然后与实际值比较，反向传播，更新所有参数，以此降低损失函数，而这整个过程是并行的。</p><blockquote><p>Decoder 侧（<strong>四个位置同时并行</strong>）：</p><p>输入：[BOS] I love AI</p><p>​ ↓ ↓ ↓ ↓</p><p>​ Masked Self-Attention (整合各自能看到的前缀上下文）</p><p>​ ↓</p><p>​ 隐状态 h → Q</p><p>​ ↓</p><p>​ Cross-Attention（与 Z 的 K、V 结合）</p><p>​ （从源序列里提取对应内容）</p><p>​ ↓</p><p>​ FFN</p><p>​ ↓</p><p>预测： I love AI [EOS]</p></blockquote><p>明白了这点，我们也明白了Q / K / V 的来源。这是 Cross-Attention 与 Self-Attention 最本质的区别。在 Self-Attention 中，Q、K、V 三者同源；但在 Cross-Attention 中，它们实现了“跨界握手”。这也就是Cross-Attention 做的事：拿着 Q 这个问题，去 K 里检索哪些位置最相关，然后按相关程度加权提取 V。</p><h3 id="feed-forward-network" tabindex="-1">Feed-Forward Network <a class="header-anchor" href="#feed-forward-network" aria-label="Permalink to &quot;Feed-Forward Network&quot;">​</a></h3><p>Decoder层的FFN与Encoder层的FFN在<strong>结构上完全相同</strong>，都是包含 <u>两个线性层</u> 和一个<em>非线性激活函数</em></p><p><img src="`+e+'" alt="image.png"></p><p>但输入的<strong>信息性质本质上不同</strong>：</p><p><strong>Encoder FFN 的输入</strong>：仅包含源输入序列的自注意力特征。</p><p><strong>Decoder FFN 的输入</strong>：包含目标输出已生成序列的特征，且这些特征已经通过 Cross-Attention 层深度融合了源输入的信息。</p><p>FFN 的权重是输入分布的函数。输入分布不同 → 梯度方向不同 → 收敛点不同。结构相同只意味着计算图相同，不意味着学到的特征相同</p><p>因此，两者在训练过程中学习到的权重完全不同</p><h3 id="linear-softmax" tabindex="-1">Linear &amp; Softmax <a class="header-anchor" href="#linear-softmax" aria-label="Permalink to &quot;Linear &amp; Softmax&quot;">​</a></h3><p>这是 Decoder 的最后两步，<strong>把 FFN 输出的向量转换成词汇表上的概率分布</strong>。没有这两个层，模型将只能停留在数学抽象层面，无法输出具体单词。</p><p><strong>Linear</strong> 层负责将来自 Decoder 最后一个 Block 输出的隐藏状态矩阵 $h$ 投射到全局词表空间： $$ logits = h * Wvocab + b $$</p><ul><li>h shape: [seq_len, d_model]</li><li>W~vocab~ shape: [d_model, vocab_size]</li><li>logits shape: [seq_len, vocab_size]</li><li>b ：可训练的偏置向量</li></ul><p>词汇表有多大，输出就有多少维。每一个维度对应词汇表里的一个 token，数值叫做 <strong>logit</strong>。代表了模型认为“下一个词是该单词”的<strong>原始信心得分</strong>。得分越高，可能性越大。</p><p>由于logit是原始得分，范围在$(-\\infty, +\\infty) $，不能直接用。因此需要 <strong>Softmax</strong> 把它转换成概率分布，这样就会产生一个长度为 $\\text{vocab_size}$ 的概率向量，每一个位置代表选择该单词的概率。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>细心的读者可能发现了， Linear 层的权重 $W_{vocab} $ 和输入 Embedding 矩阵共享同一套参数:</p><ul><li>Embedding 矩阵： [vocab_size, d_model] 把 token id → 向量</li><li>Linear 矩阵： [d_model, vocab_size] 把向量 → logits</li></ul><p>两者互为转置，<strong>本质上是用同一个参数矩阵 E（shape [vocab_size, d_model]），在 Embedding 阶段直接用行查找，在 Linear 阶段用其转置做投影</strong>，共享参数既减少了参数量，也让两端的语义空间保持一致</p></div><p>到这里为止，整个Transformer框架就走完了 🎉🎉🎉</p><p>接下去以问答的形式完成最后一些思考</p><h1 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A&quot;">​</a></h1><p>**Q： **</p><p><strong><u>什么是KV Cache ? 它为什么那么重要，它省掉了什么计算？又有什么副作用？</u></strong></p><p><strong>A</strong>：</p><p><strong>KV Cache 的核心逻辑是空间换时间，只计算当前最新输入的那个 Token 的 Q, K, V，而历史 Token 的 K 和 V 直接从内存中读取。</strong></p><p>问题根源来自自回归生成的本质：生成第 n+1 个 token 时，前 n 个 token 的 K、V 与上一步完全相同，若不加缓存则需重新计算，造成大量冗余。</p><p>KV Cache 的做法是：每计算完第 t 个 token，就将其 k~t~，v~t~写入缓存。生成第 n+1 个 token 时，仅计算新 token 的 $q_{n+1}, k_{n+1}, v_{n+1}$，将后两者追加入缓存，再用 $q_{n+1}$ 与缓存中全部 K 做点积，得到注意力权重，最后加权聚合全部 V。单步计算复杂度由重复 forward pass 降为 O(N)（N 为当前序列长度）。需要注意的是，这个 O(N) 是单步的复杂度；生成长度为 M 的序列，总复杂度仍为 O(M·N + M²)，KV Cache 消除的是冗余的重复计算，而非 Self-Attention 本身的平方复杂度——后者是独立问题，由 FlashAttention 等方法处理。</p><p>代价则是KV Cache 随序列增长而迅速增大。其占用可由以下公式估算：</p><p>$KV Cache=2 × Nlayers × d_{model} × seq_len × bytes per element$</p><p>例如 FP16 精度下，一个 7B 模型在 2048 上下文时，KV Cache 可能占用约 1GB 显存。</p><p>计算过程为：7B 模型一般是 32 层，d_model=4096，2048 token，FP16=2 bytes：</p><p>$2×32×4096×2048×2≈1.07GB$</p><p>这也就是空间换时间，瓶颈从 GPU 的计算能力转移到了<strong>显存带宽</strong></p><p><strong>Q：</strong></p><p><u><strong>为什么“首字延迟（Time To First Token）”通常比“后续字延迟（TPOT）”大得多？</strong></u></p><p><strong>A：</strong></p><p>因为KV Cache只加速了decoding阶段，并没有加速prefill阶段。因此慢的主要原因是 Prefill 阶段需要对整个 prompt 的所有 token 并行计算完整的 Self-Attention（O(N²) 复杂度），并将所有 K、V 写入缓存；而 Decode 阶段每步只计算一个新 token 的 Q 并与缓存的 K、V 做点积（O(N) 复杂度）</p><ul><li>Prefill： 用户输入 prompt，并行计算所有 token 的 KV → 存入 cache 这一步无法跳过，必须全量计算</li><li>Decode： 逐个生成新 token，每步只算新 Q，KV 从 cache 取 这一步是 KV Cache 真正发挥作用的地方</li></ul><p><strong>Q：</strong></p><p><u><strong>为什么AI会一个字一个字地蹦(Streaming)？</strong></u></p><p><strong>A：</strong></p><p>因为模型是逐token生成的，服务端可以逐 token 推送但是也可以等生成完成后一次性返回。Streaming 是<strong>工程层决策</strong>，服务端逐 token 推送依赖的是 SSE（Server-Sent Events）或 WebSocket 等流式传输协议</p><p><strong>Q：</strong></p><p><u><strong>为什么输入越长回复越慢？</strong></u></p><p><strong>A：</strong></p><p>主要由以下两个阶段造成：</p><p><strong>Prefill 阶段</strong>：输入长度为 N 时，Self-Attention 计算量为 O(N²)，N 越大，Prefill 越慢，TTFT 越长。</p><p><strong>Decode 阶段</strong>：每步生成新 token 时，需要与缓存中所有 N 个历史 K 做点积，单步复杂度为 O(N)，输入越长，每一步 Decode 也越慢。</p><p><strong>Q：</strong></p><p><u><strong>现代GPT系列用的是什么架构？</strong></u></p><p><strong>A：</strong></p><p>在当代 LLM时代，GPT 系列使用的是 <strong>Decoder-only</strong> 架构。Decoder-only 架构从设计上就不包含独立的 Encoder 模块，因此也不存在 Cross Attention 层；输入 prompt 和待生成序列被统一处理为同一个 token 序列，通过 Causal Masked Self-Attention 建模。即原本由 Encoder 提供的“源文信息”被直接合并到了同一个输入序列中。所谓“Encoder 的数据”，现在就在序列的 Prompt（提示词） 部分，输入的 Prompt（原本属于 Encoder 的内容）和模型即将生成的回答（原本属于 Decoder 的内容）被拼接成了一个长序列，prompt 部分可以互相 attend，生成部分只能 attend 到已生成的内容。</p><p>Decoder-only 在训练目标、扩展性、和任务统一性三个维度上系统性地优于 Encoder-Decoder，因此成为了主流</p>',222)])])}const Q=o(B,[["render",O]]);export{w as __pageData,Q as default};
